// Format Grafana alert payload → one item per alert for ntfy POST.
// Grafana sends a batched payload; we explode it into per-alert items so the
// downstream HTTP Request node fires one ntfy notification per alert.

const payload = $input.first().json.body;
const alerts = payload.alerts || [];

const items = [];
for (const alert of alerts) {
  const isResolved = alert.status === 'resolved';
  const severity = (alert.labels?.severity || 'default').toLowerCase();
  const alertname = alert.labels?.alertname || 'unknown';
  const instance = alert.labels?.instance || '';

  // ntfy Priority: 1 (min) ... 5 (max).
  let priority;
  if (isResolved) {
    priority = 2;          // quiet on resolve
  } else if (severity === 'high') {
    priority = 4;          // loud
  } else {
    priority = 3;          // normal
  }

  const titlePrefix = isResolved ? '[RESOLVED]' : '[FIRING]';
  const instanceSuffix = instance ? ` (${instance})` : '';
  const title = `${titlePrefix} ${alertname}${instanceSuffix}`;

  // Body: summary first, description as detail block.
  const summary = alert.annotations?.summary || '';
  const description = alert.annotations?.description || '';
  let body;
  if (summary && description) {
    body = `${summary}\n\n${description}`;
  } else {
    body = summary || description || 'No details provided.';
  }

  // ntfy tags become emoji icons in the notification.
  let tags;
  if (isResolved) {
    tags = 'white_check_mark';
  } else if (severity === 'high') {
    tags = 'rotating_light';
  } else {
    tags = 'warning';
  }

  items.push({
    json: { title, body, priority, tags },
  });
}

// If Grafana sent the payload with no alerts (e.g., a test ping), emit a single
// debug item so we still see something rather than silently swallowing the call.
if (items.length === 0) {
  items.push({
    json: {
      title: '[DEBUG] Grafana webhook received empty alerts array',
      body: JSON.stringify(payload, null, 2).slice(0, 1500),
      priority: 2,
      tags: 'mag',
    },
  });
}

return items;
